    const trimmedRule = normalizeMatchCandidate(rule);
    if (!trimmedRule) {
      continue;
    }
    const regex = toGlobRegex(trimmedRule);
    if (candidates.some((candidate) => regex.test(candidate))) {
      return true;
    }
  }

  return false;
