  const requiresAuth = modeRequiresAuth({
    mode,
    route: input.route,
    isRoutePrivate: input.isRoutePrivate,
  });

  if (!requiresAuth) {
    return {
      mode,
      route: input.route,
      requiresAuth: false,
      allowed: true,
    };
  }

