  const raw = (input.value ?? envValue ?? "").trim();
  if (!raw) {
    return [];
  }

  return raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

export function resolveDocsAuthMode(config: Pick<DocsConfig, "auth">): DocsAuthMode {
  if (!config.auth?.enabled) {
    return "public";
  }

  return config.auth.mode;
