","import { assertValidBlogPublishMetadata, resolveBlogLastBuildDate } from "./blog";
import type { BlogPost, DocsManifest } from "./types";

export interface RSSFeedOptions {
  title: string;
  description: string;
  /** Public URL for the channel (often the blog index page). */
  link: string;
  language?: string;
  /**
   * Absolute URL for this feed’s `atom:link rel="self"`.
   * Default: `{link}{manifest.blog.feedPath}` when `link` has no path, or join with manifest feed path.
   */
  feedHref?: string;
  /**
   * Absolute permalink for a post. Use when public blog URLs differ from `post.path` on the manifest
   * (e.g. docs at `/docs` but the app serves posts under `/blog/[slug]`).
   */
  itemHref?: (post: BlogPost) => string;
}

/**
 * Generate RSS 2.0 feed XML from blog posts
 */
export function generateRSSFeed(
  manifest: DocsManifest,
  options: RSSFeedOptions
): string {
  const { title, description, link, language = "en" } = options;

  const normalizedLink = link.replace(/\/+$/, "");
  const orderedIds = manifest.blog?.postOrder ?? [];
  const orderedPostsFromManifest = orderedIds
    .map((id) => manifest.posts[id])
    .filter((post): post is BlogPost => Boolean(post));
  const posts =
    orderedPostsFromManifest.length > 0
      ? orderedPostsFromManifest
      : Object.values(manifest.posts).sort((left, right) => {
          const leftDate = assertValidBlogPublishMetadata(left).timestamp;
          const rightDate = assertValidBlogPublishMetadata(right).timestamp;
          if (leftDate !== rightDate) {
            return rightDate - leftDate;
          }
          return left.slug.localeCompare(right.slug, "en", {
            sensitivity: "variant",
            numeric: true,
          });
        });

  const items = posts
    .map((post) => {
      const publish = assertValidBlogPublishMetadata(post);
      const postLink = options.itemHref
        ? options.itemHref(post)
        : `${normalizedLink}${post.path}`;
      const descriptionValue = post.excerpt ?? post.summary;
      return `
    <item>
      <title><![CDATA[${post.title}]]></title>
      <link>${escapeXml(postLink)}</link>
      <guid isPermaLink="true">${escapeXml(postLink)}</guid>
      <pubDate>${new Date(publish.publishedAt).toUTCString()}</pubDate>
      ${descriptionValue ? `<description><![CDATA[${descriptionValue}]]></description>` : ""}
      ${post.author ? `<author>${escapeXml(post.author)}</author>` : ""}
      ${post.tags.map((tag) => `<category>${escapeXml(tag)}</category>`).join("\n      ")}
    </item>
  `;
    })
    .join("");

  const feedPath = manifest.blog?.feedPath ?? "/rss.xml";
  const feedLink = options.feedHref ?? `${normalizedLink}${feedPath}`;
  const lastBuildDate = resolveBlogLastBuildDate(posts);

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(title)}</title>
    <description>${escapeXml(description)}</description>
    <link>${escapeXml(normalizedLink)}</link>
    <language>${escapeXml(language)}</language>
    <lastBuildDate>${lastBuildDate}</lastBuildDate>
    <atom:link href="${escapeXml(feedLink)}" rel="self" type="application/rss+xml"/>
    ${items}
  </channel>
</rss>`;
}

function escapeXml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}
","import { redactSensitivePayload } from "./security";
import type { DocsSearchScope } from "./search";

export const CANONICAL_DOCS_ANALYTICS_EVENT_NAMES = [
  "docs.pageview",
  "docs.search",
  "docs.search_result_click",
  "docs.external_click",
] as const;

export type DocsAnalyticsEventName =
  (typeof CANONICAL_DOCS_ANALYTICS_EVENT_NAMES)[number];

export interface DocsAnalyticsEvent {
  name: DocsAnalyticsEventName;
  timestamp: string;
  route: string;
  version?: string;
  sidebarId?: string;
  searchScope?: DocsSearchScope;
  resultCount?: number;
  targetUrl?: string;
}

export interface DocsAnalyticsEmitInput {
  enabled: boolean;
  respectDnt: boolean;
  event: DocsAnalyticsEvent;
  emit: (event: DocsAnalyticsEvent) => void;
  doNotTrackValue?: string | null;
}

export interface CreateDocsAnalyticsEmitterInput {
  enabled?: boolean;
  respectDnt?: boolean;
  emit: (event: DocsAnalyticsEvent) => void;
  doNotTrackValue?: string | null;
}

const SENSITIVE_QUERY_KEY_PATTERN =
  /(token|secret|key|authorization|cookie|session|password|sig)/i;

function isDocsSearchScope(value: unknown): value is DocsSearchScope {
  return value === "docs" || value === "api" || value === "blog";
}

function resolveDoNotTrackValue(input?: string | null): string | null {
  if (typeof input === "string") {
    return input;
  }

  const globalValue = globalThis as Record<string, unknown>;
  const navigatorValue =
    typeof globalValue.navigator === "object" && globalValue.navigator !== null
      ? (globalValue.navigator as Record<string, unknown>).doNotTrack
      : undefined;
  if (typeof navigatorValue === "string") {
    return navigatorValue;
  }

  const windowValue =
    typeof globalValue.window === "object" && globalValue.window !== null
      ? (globalValue.window as Record<string, unknown>).doNotTrack
      : undefined;
  if (typeof windowValue === "string") {
    return windowValue;
  }

  return null;
}

function sanitizePathLikeValue(value: string): string {
  if (!value) {
    return value;
  }

  try {
    const parsed = new URL(value, "https://docsfn.local");
    const nextParams = new URLSearchParams();

    for (const [key, paramValue] of parsed.searchParams.entries()) {
      if (SENSITIVE_QUERY_KEY_PATTERN.test(key)) {
        continue;
      }
      const redacted = redactSensitivePayload(paramValue);
      if (typeof redacted !== "string" || redacted === "[REDACTED]") {
        continue;
      }
      nextParams.append(key, redacted);
    }

    parsed.search = nextParams.toString();
    const normalizedPath = `${parsed.pathname}${parsed.search}${parsed.hash}`;

    if (value.startsWith("http://") || value.startsWith("https://")) {
      return `${parsed.origin}${normalizedPath}`;
    }

    return normalizedPath;
  } catch {
    const redacted = redactSensitivePayload(value);
    return typeof redacted === "string" ? redacted : "";
  }
}

export function isCanonicalDocsAnalyticsEventName(
  value: string
): value is DocsAnalyticsEventName {
  return (CANONICAL_DOCS_ANALYTICS_EVENT_NAMES as readonly string[]).includes(value);
}

export function sanitizeDocsAnalyticsEvent(
  event: DocsAnalyticsEvent
): DocsAnalyticsEvent | null {
  if (!isCanonicalDocsAnalyticsEventName(event.name)) {
    return null;
  }

  const route = sanitizePathLikeValue(event.route).trim();
  if (!route) {
    return null;
  }

  const timestamp =
    typeof event.timestamp === "string" && event.timestamp.trim().length > 0
      ? event.timestamp
      : new Date().toISOString();

  const sanitized: DocsAnalyticsEvent = {
    name: event.name,
    timestamp,
    route,
  };

  if (typeof event.version === "string" && event.version.trim().length > 0) {
    sanitized.version = sanitizePathLikeValue(event.version.trim());
  }

  if (typeof event.sidebarId === "string" && event.sidebarId.trim().length > 0) {
    sanitized.sidebarId = sanitizePathLikeValue(event.sidebarId.trim());
  }

  if (isDocsSearchScope(event.searchScope)) {
    sanitized.searchScope = event.searchScope;
  }

  if (
    typeof event.resultCount === "number" &&
    Number.isFinite(event.resultCount) &&
    event.resultCount >= 0
  ) {
    sanitized.resultCount = Math.floor(event.resultCount);
  }

  if (typeof event.targetUrl === "string" && event.targetUrl.trim().length > 0) {
    sanitized.targetUrl = sanitizePathLikeValue(event.targetUrl.trim());
  }

  return sanitized;
}

export function maybeEmitAnalyticsEvent(input: DocsAnalyticsEmitInput): boolean {
  if (!input.enabled) {
    return false;
  }

  const doNotTrackValue = resolveDoNotTrackValue(input.doNotTrackValue);
  if (input.respectDnt && doNotTrackValue === "1") {
    return false;
  }

  const sanitizedEvent = sanitizeDocsAnalyticsEvent(input.event);
  if (!sanitizedEvent) {
    return false;
  }

  input.emit(sanitizedEvent);
  return true;
}

export function createDocsAnalyticsEmitter(input: CreateDocsAnalyticsEmitterInput) {
  const enabled = input.enabled ?? false;
  const respectDnt = input.respectDnt ?? true;

  return (event: DocsAnalyticsEvent) =>
    maybeEmitAnalyticsEvent({
      enabled,
      respectDnt,
      emit: input.emit,
      doNotTrackValue: input.doNotTrackValue,
      event,
    });
}
","import type { ApiReference, BlogPost, DocPage, DocsManifest } from "./types";

export interface BuildLlmsTxtOptions {
  /** When provided, prefixes generated links with this absolute origin (eg. "https://authfn.superfunctions.dev"). */
  canonicalUrl?: string;
  /** Glob-style include patterns (e.g., ["docs/**"]). When omitted, every page is included. */
  includePages?: string[];
  /** Glob-style exclude patterns (e.g., ["docs/blog/**"]). */
  excludePages?: string[];
  /** Whether to append blog posts. Default true. */
  includeBlog?: boolean;
  /** Whether to append OpenAPI summary lines. Default true. */
  includeOpenApi?: boolean;
}

export interface BuildLlmsFullTxtOptions extends BuildLlmsTxtOptions {
  /** Whether to embed full OpenAPI JSON. Default false (a summary is appended instead). */
  embedOpenApiSpec?: boolean;
}

export interface LlmsTxtArtifacts {
  llmsTxt: string;
  llmsFullTxt: string;
}

interface FilteredManifest {
  pages: DocPage[];
  posts: BlogPost[];
  apis: ApiReference[];
}

function compareById<T extends { id: string }>(left: T, right: T): number {
  return left.id.localeCompare(right.id, "en", {
    sensitivity: "variant",
    numeric: true,
  });
}

function pathFor(canonicalUrl: string | undefined, route: string): string {
  if (!canonicalUrl) {
    return route;
  }
  const trimmed = canonicalUrl.replace(/\/+$/, "");
  const prefixed = route.startsWith("/") ? route : `/${route}`;
  return `${trimmed}${prefixed}`;
}

function globToRegExp(pattern: string): RegExp {
  const escaped = pattern.replace(/[.+^${}()|[\]\\]/g, (match) => `\\${match}`);
  const expanded = escaped
    .replace(/\*\*\//g, "(?:.+/)?")
    .replace(/\*\*/g, ".*")
    .replace(/\*/g, "[^/]*")
    .replace(/\?/g, "[^/]");
  return new RegExp(`^${expanded}$`);
}

function matchesAnyGlob(value: string, patterns: string[] | undefined): boolean {
  if (!patterns || patterns.length === 0) return false;
  return patterns.some((pattern) => globToRegExp(pattern).test(value));
}

function selectPages(manifest: DocsManifest, options: BuildLlmsTxtOptions): DocPage[] {
  const include = options.includePages;
  const exclude = options.excludePages;
  const pages = Object.values(manifest.pages);
  return pages
    .filter((page) => {
      if (include && include.length > 0 && !matchesAnyGlob(page.id, include)) {
        return false;
      }
      if (exclude && matchesAnyGlob(page.id, exclude)) {
        return false;
      }
      return true;
    })
    .sort(compareById);
}

function selectPosts(manifest: DocsManifest, options: BuildLlmsTxtOptions): BlogPost[] {
  if (options.includeBlog === false) return [];
  const posts = Object.values(manifest.posts).filter((post) => !post.draft);
  return posts.sort(compareById);
}

function selectApis(manifest: DocsManifest, options: BuildLlmsTxtOptions): ApiReference[] {
  if (options.includeOpenApi === false) return [];
  return Object.values(manifest.apis).sort(compareById);
}

function filterManifest(manifest: DocsManifest, options: BuildLlmsTxtOptions): FilteredManifest {
  return {
    pages: selectPages(manifest, options),
    posts: selectPosts(manifest, options),
    apis: selectApis(manifest, options),
  };
}

function describePage(page: DocPage): string {
  const description = page.description ?? page.frontmatter?.description;
  return typeof description === "string" && description.length > 0 ? description : page.title;
}

function describePost(post: BlogPost): string {
  return post.summary ?? post.excerpt ?? post.title;
}

function summarizeOpenApiSpec(api: ApiReference): string[] {
  const lines: string[] = [];
  const spec = api.spec?.spec ?? api.spec;
  const paths = spec?.paths;
  if (!paths || typeof paths !== "object") return lines;

  for (const [pathName, methodsRaw] of Object.entries(paths)) {
    if (!methodsRaw || typeof methodsRaw !== "object") continue;
    for (const [method, operationRaw] of Object.entries(methodsRaw as Record<string, unknown>)) {
      if (method === "parameters") continue;
      const operation = operationRaw as
        | { summary?: string; operationId?: string; description?: string }
        | undefined;
      if (!operation || typeof operation !== "object") continue;

      const summary =
        operation.summary ?? operation.description ?? operation.operationId ?? "(no summary)";
      lines.push(`- ${method.toUpperCase()} ${pathName} — ${summary}`);
    }
  }
  return lines;
}

function buildHeader(manifest: DocsManifest): string {
  const lines = [`# ${manifest.site.title}`];
  if (manifest.site.description) {
    lines.push("", `> ${manifest.site.description}`);
  }
  return lines.join("\n");
}

export function buildLlmsTxt(manifest: DocsManifest, options: BuildLlmsTxtOptions = {}): string {
  const filtered = filterManifest(manifest, options);
  const lines: string[] = [];

  lines.push(buildHeader(manifest));
  lines.push("");

  if (filtered.pages.length > 0) {
    lines.push("## Documentation");
    lines.push("");
    for (const page of filtered.pages) {
      const url = pathFor(options.canonicalUrl, page.path);
      lines.push(`- [${page.title}](${url}) — ${describePage(page)}`);
    }
    lines.push("");
  }

  if (filtered.posts.length > 0) {
    lines.push("## Blog");
    lines.push("");
    for (const post of filtered.posts) {
      const url = pathFor(options.canonicalUrl, post.path);
      lines.push(`- [${post.title}](${url}) — ${describePost(post)}`);
    }
    lines.push("");
  }

  if (filtered.apis.length > 0) {
    lines.push("## API Reference");
    lines.push("");
    for (const api of filtered.apis) {
      const url = pathFor(options.canonicalUrl, api.path);
      lines.push(`- [${api.title}](${url})`);
      const summaries = summarizeOpenApiSpec(api);
      for (const summary of summaries) {
        lines.push(`  ${summary}`);
      }
    }
    lines.push("");
  }

  return `${lines.join("\n").replace(/\n+$/, "")}\n`;
}

export function buildLlmsFullTxt(
  manifest: DocsManifest,
  options: BuildLlmsFullTxtOptions = {}
): string {
  const filtered = filterManifest(manifest, options);
  const lines: string[] = [];

  lines.push(buildHeader(manifest));
  lines.push("");
  lines.push(
    "This file concatenates the full text of every documentation page so it can be loaded into",
    "an LLM-based assistant in a single shot. For programmatic access, prefer the MCP server",
    "or the structured manifest emitted alongside this file.",
    ""
  );

  if (filtered.pages.length > 0) {
    lines.push("# Documentation");
    lines.push("");
    for (const page of filtered.pages) {
      lines.push(`<!-- page:${page.id} path:${page.path} -->`);
      lines.push(`# ${page.title}`);
      if (typeof page.description === "string" && page.description.length > 0) {
        lines.push("");
        lines.push(`> ${page.description}`);
      }
      lines.push("");
      lines.push(page.body.trimEnd());
      lines.push("");
      lines.push("---");
      lines.push("");
    }
  }

  if (filtered.posts.length > 0) {
    lines.push("# Blog");
    lines.push("");
    for (const post of filtered.posts) {
      lines.push(`<!-- post:${post.id} path:${post.path} date:${post.date} -->`);
      lines.push(`# ${post.title}`);
      lines.push("");
      lines.push(post.body.trimEnd());
      lines.push("");
      lines.push("---");
      lines.push("");
    }
  }

  if (filtered.apis.length > 0) {
    lines.push("# API Reference");
    lines.push("");
    for (const api of filtered.apis) {
      lines.push(`<!-- api:${api.id} path:${api.path} -->`);
      lines.push(`## ${api.title}`);
      lines.push("");
      const summaries = summarizeOpenApiSpec(api);
      if (summaries.length > 0) {
        for (const summary of summaries) {
          lines.push(summary);
        }
        lines.push("");
      }
      if (options.embedOpenApiSpec) {
        const spec = api.spec?.spec ?? api.spec;
        if (spec) {
          lines.push("```json");
          lines.push(JSON.stringify(spec, null, 2));
          lines.push("```");
          lines.push("");
        }
      }
    }
  }

  return `${lines.join("\n").replace(/\n+$/, "")}\n`;
}

export function buildLlmsTxtArtifacts(
  manifest: DocsManifest,
  options: BuildLlmsFullTxtOptions = {}
): LlmsTxtArtifacts {
  return {
    llmsTxt: buildLlmsTxt(manifest, options),
    llmsFullTxt: buildLlmsFullTxt(manifest, options),
  };
}
","import type { CompiledContentArtifact, CompiledContentBlock } from "./types";

export interface ResolveMarkdownRelativeLinksInput {
  compiled: CompiledContentArtifact;
  route: string;
  sourcePath?: string;
  isIndexRoute?: boolean;
}

const HREF_ATTRIBUTE_REGEX = /(<a\b[^>]*\bhref=)(["'])([^"']+)\2/gi;
const EXTERNAL_OR_SPECIAL_HREF_REGEX = /^(?:[a-z][a-z0-9+.-]*:|\/\/|#|\/|\{)/i;

export function resolveMarkdownRelativeLinks({
  compiled,
  route,
  sourcePath,
  isIndexRoute = false,
}: ResolveMarkdownRelativeLinksInput): CompiledContentArtifact {
  const baseRoute = resolveBaseRoute(route, sourcePath, isIndexRoute);

  return {
    ...compiled,
    blocks: resolveBlocks(compiled.blocks, baseRoute),
  };
}

function resolveBlocks(
  blocks: CompiledContentBlock[],
  baseRoute: string,
): CompiledContentBlock[] {
  return blocks.map((block) => {
    if ("html" in block) {
      return {
        ...block,
        html: resolveHtmlLinks(block.html, baseRoute),
      };
    }

    if (block.type === "tabs") {
      return {
        ...block,
        tabs: block.tabs.map((tab) => ({
          ...tab,
          nodes: resolveBlocks(tab.nodes, baseRoute),
        })),
      };
    }

    if (block.type === "component") {
      return {
        ...block,
        children: resolveBlocks(block.children, baseRoute),
      };
    }

    return block;
  });
}

function resolveHtmlLinks(html: string, baseRoute: string): string {
  return html.replace(HREF_ATTRIBUTE_REGEX, (match, prefix, quote, href) => {
    if (EXTERNAL_OR_SPECIAL_HREF_REGEX.test(href)) {
      return match;
    }

    const resolvedHref = resolveHref(href, baseRoute);
    return `${prefix}${quote}${resolvedHref}${quote}`;
  });
}

function resolveHref(href: string, baseRoute: string): string {
  try {
    const resolved = new URL(href, `https://docs.local${baseRoute}/`);
    return `${resolved.pathname}${resolved.search}${resolved.hash}`;
  } catch {
    return href;
  }
}

function resolveBaseRoute(
  route: string,
  sourcePath: string | undefined,
  isIndexRoute: boolean,
): string {
  const normalizedRoute = normalizeAbsolutePath(route);

  if (isIndexRoute || (sourcePath && /(?:^|\/)index\.mdx?$/i.test(sourcePath))) {
    return normalizedRoute;
  }

  const separatorIndex = normalizedRoute.lastIndexOf("/");
  if (separatorIndex <= 0) {
    return "/";
  }

  return normalizedRoute.slice(0, separatorIndex);
}

function normalizeAbsolutePath(path: string): string {
  const prefixed = path.startsWith("/") ? path : `/${path}`;
  return prefixed.length > 1 ? prefixed.replace(/\/+$/, "") : prefixed;
}
