function isRemotePath(value: string): boolean {
  return /^[a-z][a-z0-9+.-]*:\/\//i.test(value);
}

function ensureLocalPath(value: string): void {
  if (isRemotePath(value)) {
    throw new ConfigLoaderError("CLIFN_CONFIG_NOT_FOUND", "Remote config URLs are not supported.");
  }
}

function resolveCandidates(options: ConfigLoaderOptions<unknown>): readonly string[] {
  if (options.configPath) {
    return [options.configPath];
  }

  const candidates = options.candidates && options.candidates.length > 0 ? [...options.candidates] : [...DEFAULT_CANDIDATES];
  if (candidates.length > 32) {
    throw new ConfigLoaderError("CLIFN_CONFIG_INVALID", "Config candidate list exceeds the limit of 32 entries.");
  }
  return candidates;
}

async function resolveConfigValue(value: unknown): Promise<unknown> {
  const resolved = typeof value === "function" ? value() : value;
  return await Promise.resolve(resolved);
}

function resolveExportValue(moduleValue: unknown, exportNames: readonly string[]): unknown {
  if (moduleValue && typeof moduleValue === "object") {
    const record = moduleValue as Record<string, unknown>;
    const prototype = Object.getPrototypeOf(record);
    const looksLikeModuleWrapper = record.__esModule === true || prototype === null || prototype !== Object.prototype;

    if (!looksLikeModuleWrapper) {
      return moduleValue;
    }

    if (record.default !== undefined) {
      return record.default;
    }

    for (const exportName of exportNames) {
      if (record[exportName] !== undefined) {
        return record[exportName];
      }
    }
  }

  return moduleValue;
}

async function loadJsonConfig(resolvedPath: string): Promise<unknown> {
  try {
    const raw = await readFile(resolvedPath, "utf8");
    return JSON.parse(raw) as unknown;
  } catch (error) {
    const message = error instanceof Error ? error.message : "Invalid JSON config";
    throw new ConfigLoaderError("CLIFN_CONFIG_INVALID", message);
  }
}

async function loadModuleConfig(resolvedPath: string): Promise<unknown> {
  const extension = path.extname(resolvedPath).toLowerCase();

  if (!SUPPORTED_EXTENSIONS.has(extension)) {
    throw new ConfigLoaderError(
      "CLIFN_CONFIG_UNSUPPORTED",
      `Unsupported config extension: ${extension || "<none>"}`
    );
  }

  if (extension === ".json") {
    return loadJsonConfig(resolvedPath);
  }

  if (extension === ".ts") {
    const jiti = createJiti(path.dirname(resolvedPath), {
      moduleCache: false,
      interopDefault: false,
      extensions: [".ts", ".js", ".mjs", ".cjs", ".json"],
    });
    return await jiti.import(resolvedPath);
  }

  return import(pathToFileURL(resolvedPath).href);
}

export function defineConfig<T>(config: T): T {
  return config;
}

export async function loadConfig<T>(options: ConfigLoaderOptions<T> = {}): Promise<LoadedConfig<T>> {
  const cwd = options.cwd ?? process.cwd();
  const candidates = resolveCandidates(options);
  const exportNames = options.exportNames ?? [];

  for (const candidate of candidates) {
    ensureLocalPath(candidate);

    const resolvedPath = path.isAbsolute(candidate) ? candidate : path.resolve(cwd, candidate);
    if (!existsSync(resolvedPath)) {
      continue;
    }

    try {
      const loadedModule = await loadModuleConfig(resolvedPath);
      const configValue = await resolveConfigValue(resolveExportValue(loadedModule, exportNames));
      const validated = options.validate ? options.validate(configValue, resolvedPath) : (configValue as T);
      return {
        config: validated,
        path: resolvedPath,
      };
    } catch (error) {
      if (error instanceof ConfigLoaderError) {
        throw error;
      }
      const message = error instanceof Error ? error.message : `Config loading failed for ${resolvedPath}`;
      throw new ConfigLoaderError("CLIFN_CONFIG_INVALID", message);
    }
  }

  if (options.configPath) {
    throw new ConfigLoaderError("CLIFN_CONFIG_NOT_FOUND", `Config file not found: ${options.configPath}`);
  }

  throw new ConfigLoaderError(
    "CLIFN_CONFIG_NOT_FOUND",
    `Config file not found. Checked: ${candidates.join(", ")}`
  );
}
export type EnvErrorCode = "CLIFN_ENV_INVALID" | "CLIFN_ENV_MISSING" | "CLIFN_ENV_OUT_OF_RANGE";

class EnvError extends Error {
  readonly code: EnvErrorCode;

  constructor(code: EnvErrorCode, message: string) {
    super(message);
    this.name = "EnvError";
    this.code = code;
  }
}

export interface StringEnvOptions {
  defaultValue?: string;
  allowEmpty?: boolean;
  env?: NodeJS.ProcessEnv;
}

export interface IntEnvOptions {
  defaultValue?: number;
  min?: number;
  max?: number;
  env?: NodeJS.ProcessEnv;
}

export interface BooleanEnvOptions {
  defaultValue?: boolean;
  env?: NodeJS.ProcessEnv;
}

function getEnvValue(key: string, env?: NodeJS.ProcessEnv): string | undefined {
  return (env ?? process.env)[key];
}

export function readRequiredStringEnv(key: string, options: Omit<StringEnvOptions, "defaultValue"> = {}): string {
  const raw = getEnvValue(key, options.env);
  if (raw === undefined || (!options.allowEmpty && raw.trim().length === 0)) {
    throw new EnvError("CLIFN_ENV_MISSING", `${key} is required`);
  }
  return raw;
}

export function readStringEnv(key: string, options: StringEnvOptions = {}): string {
  const raw = getEnvValue(key, options.env);
  if (raw === undefined) {
    if (options.defaultValue !== undefined) {
      return options.defaultValue;
    }
    throw new EnvError("CLIFN_ENV_MISSING", `${key} is required`);
  }

  if (!options.allowEmpty && raw.trim().length === 0) {
    throw new EnvError("CLIFN_ENV_INVALID", `${key} must not be empty`);
  }

  return raw;
}

export function readIntEnv(key: string, options: IntEnvOptions = {}): number {
  const raw = getEnvValue(key, options.env);
  if (raw === undefined || raw === "") {
    if (options.defaultValue !== undefined) {
      return validateInt(key, options.defaultValue, options);
    }
    throw new EnvError("CLIFN_ENV_MISSING", `${key} is required`);
  }

  const parsed = Number.parseInt(raw, 10);
  if (!Number.isInteger(parsed) || String(parsed) !== raw.trim()) {
    throw new EnvError("CLIFN_ENV_INVALID", `${key} must be an integer`);
  }

  return validateInt(key, parsed, options);
}

export function readBooleanEnv(key: string, options: BooleanEnvOptions = {}): boolean {
  const raw = getEnvValue(key, options.env);
  if (raw === undefined || raw === "") {
    if (options.defaultValue !== undefined) {
      return options.defaultValue;
    }
    throw new EnvError("CLIFN_ENV_MISSING", `${key} is required`);
  }

  const normalized = raw.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) {
    return true;
  }
  if (["0", "false", "no", "off"].includes(normalized)) {
    return false;
  }

  throw new EnvError("CLIFN_ENV_INVALID", `${key} must be a boolean-like value`);
}

function validateInt(key: string, value: number, options: IntEnvOptions): number {
  if (!Number.isInteger(value)) {
    throw new EnvError("CLIFN_ENV_INVALID", `${key} must be an integer`);
  }

  if (options.min !== undefined && value < options.min) {
    throw new EnvError("CLIFN_ENV_OUT_OF_RANGE", `${key} must be >= ${options.min}`);
  }

  if (options.max !== undefined && value > options.max) {
    throw new EnvError("CLIFN_ENV_OUT_OF_RANGE", `${key} must be <= ${options.max}`);
  }

  return value;
}
const SENSITIVE_KEY_PATTERN =
  /(authorization|token|secret|password|cookie|api[-_]?key|session[-_]?id|access[-_]?key|refresh[-_]?token)/i;

export type DiagnosticSeverity = "error" | "warning" | "info";
export type DiagnosticDetails = Record<string, unknown>;

export interface Diagnostic {
  code: string;
  severity: DiagnosticSeverity;
  message: string;
  path?: string;
  details?: DiagnosticDetails;
}

export interface DiagnosticReport {
  ok: boolean;
  diagnostics: readonly Diagnostic[];
}

const SEVERITY_ORDER: Record<DiagnosticSeverity, number> = {
  error: 0,
  warning: 1,
  info: 2,
};

const CIRCULAR_SENTINEL = "[Circular]";

function cloneValue(value: unknown, seen = new WeakSet<object>()): unknown {
  if (Array.isArray(value)) {
    if (seen.has(value)) {
      return CIRCULAR_SENTINEL;
    }

    seen.add(value);
    try {
      return value.map((item) => cloneValue(item, seen));
    } finally {
      seen.delete(value);
    }
  }

  if (value && typeof value === "object") {
    if (seen.has(value)) {
      return CIRCULAR_SENTINEL;
    }

    seen.add(value);
    try {
      return Object.fromEntries(
        Object.entries(value as Record<string, unknown>).map(([key, nested]) => [key, cloneValue(nested, seen)])
      );
    } finally {
      seen.delete(value);
    }
  }

  return value;
}

export function redactValue(value: unknown, seen = new WeakSet<object>()): unknown {
  if (Array.isArray(value)) {
    if (seen.has(value)) {
      return CIRCULAR_SENTINEL;
    }

    seen.add(value);
    try {
      return value.map((item) => redactValue(item, seen));
    } finally {
      seen.delete(value);
    }
  }

  if (value && typeof value === "object") {
    if (seen.has(value)) {
      return CIRCULAR_SENTINEL;
    }

    seen.add(value);
    try {
      return Object.fromEntries(
        Object.entries(value as Record<string, unknown>).map(([key, nested]) => {
          if (SENSITIVE_KEY_PATTERN.test(key)) {
            return [key, "[REDACTED]"];
          }
          return [key, redactValue(nested, seen)];
        })
      );
    } finally {
      seen.delete(value);
    }
  }

  return value;
}

function normalizeForSerialization(value: unknown, seen = new WeakSet<object>()): unknown {
  if (Array.isArray(value)) {
    if (seen.has(value)) {
      return CIRCULAR_SENTINEL;
    }

    seen.add(value);
    try {
      return value.map((item) => normalizeForSerialization(item, seen));
    } finally {
      seen.delete(value);
    }
  }

  if (value && typeof value === "object") {
    if (seen.has(value)) {
      return CIRCULAR_SENTINEL;
    }

    seen.add(value);
    try {
      return Object.fromEntries(
        Object.keys(value as Record<string, unknown>)
          .sort((left, right) => left.localeCompare(right))
          .map((key) => [key, normalizeForSerialization((value as Record<string, unknown>)[key], seen)])
      );
    } finally {
      seen.delete(value);
    }
  }

  return value;
}

function compareDiagnostics(left: Diagnostic, right: Diagnostic): number {
  return (
    SEVERITY_ORDER[left.severity] - SEVERITY_ORDER[right.severity] ||
    left.code.localeCompare(right.code) ||
    left.message.localeCompare(right.message) ||
    (left.path ?? "").localeCompare(right.path ?? "")
  );
}

function toReport(input: readonly Diagnostic[]): DiagnosticReport {
  const diagnostics = sortDiagnostics(redactDiagnostics(input));
  return {
    ok: diagnostics.every((diagnostic) => diagnostic.severity !== "error"),
    diagnostics,
  };
}

function stableStringify(value: unknown): string {
  return JSON.stringify(normalizeForSerialization(value));
}

export function createDiagnostic(input: Diagnostic): Diagnostic {
  return {
    code: input.code,
    severity: input.severity,
    message: input.message,
    path: input.path,
    details: input.details ? (cloneValue(input.details) as DiagnosticDetails) : undefined,
  };
}

export function sortDiagnostics(input: readonly Diagnostic[]): Diagnostic[] {
  return input
    .map((diagnostic, index) => ({
      diagnostic: createDiagnostic(diagnostic),
      index,
    }))
    .sort((left, right) => compareDiagnostics(left.diagnostic, right.diagnostic) || left.index - right.index)
    .map((entry) => entry.diagnostic);
}

export function redactDiagnostics(input: readonly Diagnostic[]): Diagnostic[] {
  return input.map((diagnostic) => ({
    ...createDiagnostic(diagnostic),
    details: diagnostic.details ? (redactValue(diagnostic.details) as DiagnosticDetails) : undefined,
  }));
}

export function formatDiagnosticsText(input: readonly Diagnostic[]): string {
  const report = toReport(input);
  const lines: string[] = [];

  for (const diagnostic of report.diagnostics) {
    lines.push(`[${diagnostic.severity}] ${diagnostic.code}: ${diagnostic.message}`);

    if (diagnostic.path) {
      lines.push(`  path: ${diagnostic.path}`);
    }

    if (diagnostic.details) {
      lines.push(`  details: ${stableStringify(diagnostic.details)}`);
    }
  }

  return `${lines.join("\n")}\n`;
}

export function formatDiagnosticsJson(input: readonly Diagnostic[]): string {
  return `${stableStringify(toReport(input))}\n`;
}

