import { createRouter } from '../../../../packages/http/src/router.js';
import type { Route } from '../../../../packages/http/src/types.js';
import { z } from 'zod';
import type { IMemoryFn } from '../core/config';
import { requireScope, type MemoryScope } from '../storage/adapter';

/** The host authenticates on every request; caller JSON cannot choose its tenant. */
export function createMemoryRouter(memory: IMemoryFn, options: {
  authorize(request: Request): Promise<MemoryScope | null>;
  maxBodyBytes?: number;
}) {
  const tags = z.array(z.string().min(1)).default([]);
  const add = z.object({ content: z.string().min(1), containerTags: tags, metadata: z.record(z.unknown()).optional() }).strict();
  const search = z.object({ q: z.string().min(1), containerTags: tags, filters: z.record(z.unknown()).optional(), limit: z.number().int().min(1).max(100).optional(), threshold: z.number().min(-1).max(1).optional() }).strict();
  const routes: Route[] = [
    { method: 'POST', path: '/v1/memories', handler: async (request, ctx) => {
      const scope = await options.authorize(request);
      if (!scope) return Response.json({ error: 'UNAUTHORIZED' }, { status: 401 });
      requireScope(scope.tenantId, scope.containerTags);
      const input = add.safeParse(await ctx.json());
      if (!input.success) return Response.json({ error: 'INVALID_INPUT' }, { status: 400 });
      return Response.json(await memory.add({ ...input.data, tenantId: scope.tenantId, containerTags: [...scope.containerTags, ...input.data.containerTags] }));
    } },
    { method: 'POST', path: '/v1/memories/search', handler: async (request, ctx) => {
      const scope = await options.authorize(request);
      if (!scope) return Response.json({ error: 'UNAUTHORIZED' }, { status: 401 });
      requireScope(scope.tenantId, scope.containerTags);
      const input = search.safeParse(await ctx.json());
      if (!input.success) return Response.json({ error: 'INVALID_INPUT' }, { status: 400 });
      return Response.json(await memory.search({ ...input.data, tenantId: scope.tenantId, containerTags: [...scope.containerTags, ...input.data.containerTags] }));
    } },
  ];
  return createRouter({ routes, maxBodyBytes: options.maxBodyBytes ?? 1024 * 1024 });
}
import { requireScope, type MemoryScope } from '../storage/adapter';
import type { Transport } from '@modelcontextprotocol/sdk/shared/transport.js';
import {
  McpFnRegistry,
  createMcpFnServer,
  structuredResult,
  type McpFnManifest,
  type McpFnObjectSchema,
  type McpFnServer,
} from '@mcpfn/core';

import type { IMemoryFn } from '../core/config';

const ADD_MEMORY_OUTPUT_SCHEMA: McpFnObjectSchema = {
  type: 'object',
  properties: {
    result: {
      type: 'object',
      properties: {
        summary: {
          type: 'object',
          properties: {
            created: { type: 'integer', minimum: 0 },
            updated: { type: 'integer', minimum: 0 },
            deduplicated: { type: 'integer', minimum: 0 },
          },
          required: ['created', 'updated', 'deduplicated'],
          additionalProperties: false,
        },
      },
      required: ['summary'],
      additionalProperties: false,
    },
  },
  required: ['result'],
  additionalProperties: false,
};

const SEARCH_MEMORIES_OUTPUT_SCHEMA: McpFnObjectSchema = {
  type: 'object',
  properties: {
    result: {
      type: 'object',
      properties: {
        results: {
          type: 'array',
          items: {
            type: 'object',
            properties: { content: { type: 'string' } },
            required: ['content'],
            additionalProperties: false,
          },
        },
        metadata: {
          type: 'object',
          properties: {
            totalFound: { type: 'integer', minimum: 0 },
            afterRerank: { type: 'integer', minimum: 0 },
            returned: { type: 'integer', minimum: 0 },
          },
          required: ['totalFound', 'returned'],
          additionalProperties: false,
        },
      },
      required: ['results', 'metadata'],
      additionalProperties: false,
    },
  },
  required: ['result'],
  additionalProperties: false,
};

export class MemoryMCP {
  readonly registry: McpFnRegistry;
  readonly server: McpFnServer;

  constructor(private readonly memory: IMemoryFn, private readonly scope: MemoryScope) {
    requireScope(scope.tenantId, scope.containerTags);
    this.registry = new McpFnRegistry()
      .register({
        name: 'add_memory',
        description: 'Add a new memory to long-term storage.',
        inputSchema: {
          type: 'object',
          properties: {
            content: {
              type: 'string',
              minLength: 1,
              description: 'The fact or information to store',
            },
            tags: {
              type: 'array',
              items: { type: 'string', minLength: 1 },
              uniqueItems: true,
              description: 'Tags used to scope and organize the memory',
            },
          },
          required: ['content'],
          additionalProperties: false,
        },
        outputSchema: ADD_MEMORY_OUTPUT_SCHEMA,
        annotations: {
          readOnlyHint: false,
          destructiveHint: false,
          idempotentHint: false,
          openWorldHint: false,
        },
        metadata: { 'mcpfn/source': 'memoryfn' },
        handler: async (args) => {
          const result = await this.memory.add({
            content: args.content as string,
            tenantId: this.scope.tenantId,
            containerTags: [...this.scope.containerTags, ...((args.tags as string[] | undefined) ?? [])],
            type: 'conversational',
          });
          return structuredResult(
            {
              result: {
                summary: {
                  created: result.summary.created,
                  updated: result.summary.updated,
                  deduplicated: result.summary.deduplicated,
                },
              },
            },
            [{ type: 'text', text: 'Memory added successfully.' }],
          );
        },
      })
      .register({
        name: 'search_memories',
        description: 'Search for memories relevant to a query.',
        inputSchema: {
          type: 'object',
          properties: {
            query: {
              type: 'string',
              minLength: 1,
              description: 'The search query',
            },
            limit: {
              type: 'integer',
              minimum: 1,
              maximum: 100,
              default: 5,
              description: 'Maximum number of results to return',
            },
            tags: {
              type: 'array',
              items: { type: 'string', minLength: 1 },
              uniqueItems: true,
              description: 'Optional memory scope tags',
            },
          },
          required: ['query'],
          additionalProperties: false,
        },
        outputSchema: SEARCH_MEMORIES_OUTPUT_SCHEMA,
        annotations: {
          readOnlyHint: true,
          destructiveHint: false,
          idempotentHint: true,
          openWorldHint: false,
        },
        metadata: { 'mcpfn/source': 'memoryfn' },
        handler: async (args) => {
          const result = await this.memory.search({
            q: args.query as string,
            limit: (args.limit as number | undefined) ?? 5,
            tenantId: this.scope.tenantId,
            containerTags: [...this.scope.containerTags, ...((args.tags as string[] | undefined) ?? [])],
          });
          const publicResult = {
            results: result.results.map((entry) => ({ content: entry.content })),
            metadata: {
              totalFound: result.metadata.totalFound,
              ...(result.metadata.afterRerank === undefined
                ? {}
                : { afterRerank: result.metadata.afterRerank }),
              returned: result.metadata.returned,
            },
          };
          const text = publicResult.results.map((entry) => `- ${entry.content}`).join('\n');
          return structuredResult(
            { result: publicResult },
            [{ type: 'text', text: text || 'No relevant memories found.' }],
          );
        },
      });

    this.server = createMcpFnServer({
      info: {
        name: 'memoryfn-mcp',
        version: '0.1.0',
        instructions: 'Store and retrieve long-term memories through MemoryFn.',
      },
      registry: this.registry,
      transports: ['stdio'],
    });
  }

  manifest(): McpFnManifest {
    return this.server.manifest();
  }

  async connect(transport: Transport): Promise<void> {
    await this.server.connect(transport);
  }

  async start(): Promise<void> {
    await this.server.serveStdio();
    console.error('MemoryFn MCP Server running on stdio');
  }

  async close(): Promise<void> {
    await this.server.close();
  }
}
import { Memory, MemoryRelationship } from '../core/types';

export interface MemoryScope { tenantId: string; containerTags: string[] }
export type MemoryInsert = MemoryScope & Partial<Omit<Memory, keyof MemoryScope | 'revision' | 'deletedAt'>>;
export type MemoryRelationshipInsert = MemoryScope
  & Pick<MemoryRelationship, 'fromId' | 'toId'>
  & Partial<Omit<MemoryRelationship, 'fromId' | 'toId'>>;
export interface MemoryUpdate extends MemoryScope {
  id: string;
  expectedRevision: number;
  changes: Pick<Memory, 'content' | 'embedding'> & Partial<Pick<Memory, 'metadata' | 'isLatest'>>;
}
export interface MemoryDelete extends MemoryScope { id: string; expectedRevision?: number }
export interface StorageAdapter {
  /** Fixed vector dimension, shared across bundled entrypoints. */
  readonly embeddingDimensions?: number;
  close?(): Promise<void>;
  /** Commit all callback writes together, or leave storage unchanged on failure. */
  transaction?<T>(operation: (storage: StorageAdapter) => Promise<T>): Promise<T>;
  insertMemories(memories: MemoryInsert[]): Promise<Memory[]>;
  insertRelationships(relationships: MemoryRelationshipInsert[]): Promise<MemoryRelationship[]>;
  searchVectors(params: {
    tenantId: string;
    embedding: number[];
    containerTags: string[];
    filters?: Record<string, any>;
    topK: number;
    threshold?: number;
  }): Promise<Memory[]>;
  getMemory(scope: MemoryScope & { id: string }): Promise<Memory | null>;
  updateMemory(input: MemoryUpdate): Promise<Memory>;
  deleteMemory(input: MemoryDelete): Promise<void>;
}

export function requireScope(tenantId: string | undefined, tags: string[] | undefined): asserts tenantId is string {
  if (typeof tenantId !== 'string' || !tenantId.trim() || !Array.isArray(tags) || tags.some(tag => typeof tag !== 'string' || !tag.trim())) {
    throw new Error('MEMORY_SCOPE_REQUIRED');
  }
}

