export interface MemoryFnConfig {
  storage: {
    kind: 'pg' | 'qdrant' | 'sqlite' | 'memory' | 'adapter';
    adapter?: StorageAdapter;
    url?: string;
    path?: string; // for sqlite
    dbAdapter?: 'drizzle' | 'prisma' | 'kysely';
