    url: string;
    username?: string;
    password?: string;
  };
  llm?: {
    provider: 'openai';
    model: string;
    apiKey?: string;
    temperature?: number;
    maxTokens?: number;
  };
  embedder?: {
    provider: 'openai';
    model: string;
    apiKey?: string;
    dims?: number;
    batchSize?: number;
  };
  reranker?: {
    provider: 'cohere' | 'hf';
    model: string;
    apiKey?: string;
  };
  observability?: {
    watchfn?: any; // Replace with actual WatchFn type
    traceAll?: boolean;
    logPrompts?: boolean;
    logResults?: boolean;
    metrics?: {
      enabled: boolean;
      trackCosts?: boolean;
      trackLatency?: boolean;
    };
    costTracking?: {
      llm?: Record<string, { input: number; output: number }>;
      embeddings?: Record<string, number>;
    };
  };
  policies?: {
    /** Redaction is not implemented; explicitly configured values are rejected. */
    redaction?: never;
    maxMemoriesPerContainer?: never;
    maxMemorySizeBytes?: never;
  };
  cache?: {
    enabled: boolean;
    ttl: number;
    maxSize: number;
  };
  retry?: {
    maxRetries: number;
    backoff: 'exponential' | 'linear';
  };
