} from '@botfn/shared-types';
import { createPersistenceClient } from '@botfn/persistence-service/src/client';

export interface BotEnv extends DiscordBotEnv, GitHubBotEnv, LinearBotEnv {
  PERSISTENCE_SERVICE_URL: string;
