import { Hono } from 'hono';
import { verifySlackRequest } from '@botfn/slack-core';

type Bindings = {
  SLACK_SIGNING_SECRET: string;
  SLACK_BOT_TOKEN: string;
};

const app = new Hono<{ Bindings: Bindings }>();

app.post('/slack/events', async (c) => {
  const signatureValid = await verifySlackRequest(
    c.req.raw,
    c.env.SLACK_SIGNING_SECRET
  );

  if (!signatureValid) {
    return c.text('Invalid signature', 401);
  }

  const body = await c.req.json();

  // URL verification challenge
  if (body.type === 'url_verification') {
    return c.text(body.challenge);
  }

  if (body.event) {
    console.log('Received event:', body.event.type);
    return c.text('OK');
  }

  return c.text('OK');
});

export default app;
function timingSafeEqual(left: string, right: string): boolean {
  const encoder = new TextEncoder();
  const leftBytes = encoder.encode(left);
  const rightBytes = encoder.encode(right);

  if (leftBytes.length !== rightBytes.length) {
    return false;
  }

  let diff = 0;
  for (let i = 0; i < leftBytes.length; i += 1) {
    diff |= leftBytes[i] ^ rightBytes[i];
  }

  return diff === 0;
}

export async function verifySlackRequest(
  req: Request,
  signingSecret: string
): Promise<boolean> {
  const timestamp = req.headers.get('x-slack-request-timestamp');
  const signature = req.headers.get('x-slack-signature');

  if (!timestamp || !signature) {
    return false;
  }

  // Prevent replay attacks (5 minutes)
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - parseInt(timestamp)) > 60 * 5) {
    return false;
  }

  const body = await req.clone().text();
  const base = `v0:${timestamp}:${body}`;

  // Node.js crypto (works in Workers if using node compatibility or crypto polyfill)
  // Or use Web Crypto API if preferred, but HMAC in Web Crypto is more verbose
  // Here assuming standard crypto available or polyfilled

  // Actually, let's use SubtleCrypto for better compatibility with Workers/Edge
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(signingSecret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );

  const signed = await crypto.subtle.sign(
    "HMAC",
    key,
    enc.encode(base)
  );

  const hash = 'v0=' + Array.from(new Uint8Array(signed))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');

  return timingSafeEqual(signature, hash);
}
import { z } from 'zod';

/**
 * Discord interaction body schema for runtime validation
 */
const DiscordInteractionBodySchema = z.object({
  type: z.number(),
  data: z.any().optional(),
  guild_id: z.string().optional(),
  channel_id: z.string().optional(),
  member: z.any().optional(),
  user: z.any().optional(),
  token: z.string().optional(),
  version: z.number().optional(),
  id: z.string().optional(),
  application_id: z.string().optional(),
});

export type DiscordInteractionBody = z.infer<typeof DiscordInteractionBodySchema>;

/**
 * Verify Discord request signature using Ed25519
 */
export async function verifyDiscordRequest(
  request: Request,
  publicKey: string
): Promise<
  | { isValid: true; body: DiscordInteractionBody }
  | { isValid: false; body?: undefined }
> {
  const signature = request.headers.get('x-signature-ed25519');
  const timestamp = request.headers.get('x-signature-timestamp');
  const body = await request.text();

  if (!signature || !timestamp) {
    return { isValid: false };
  }

  const isValid = await verifyKey(body, signature, timestamp, publicKey);

  if (!isValid) {
    return { isValid: false };
  }

  try {
    const parsed = JSON.parse(body);
    const validated = DiscordInteractionBodySchema.safeParse(parsed);

    if (!validated.success) {
      console.error('Invalid Discord interaction body structure:', validated.error);
      return { isValid: false };
    }

    return {
      isValid: true,
      body: validated.data,
    };
  } catch (error) {
    return { isValid: false };
  }
}

/**
 * Verify Ed25519 signature
 */
async function verifyKey(
  body: string,
  signature: string,
  timestamp: string,
  publicKey: string
): Promise<boolean> {
  try {
    const encoder = new TextEncoder();
    const message = encoder.encode(timestamp + body);

    const signatureBytes = hexToBytes(signature);
    const publicKeyBytes = hexToBytes(publicKey);

    const cryptoKey = await crypto.subtle.importKey(
      'raw',
      publicKeyBytes,
      { name: 'Ed25519', namedCurve: 'Ed25519' },
      false,
      ['verify']
    );

    return await crypto.subtle.verify(
      'Ed25519',
      cryptoKey,
      signatureBytes,
      message
    );
  } catch (err) {
    console.error('Verification error:', err);
    return false;
  }
}

/**
 * Convert hex string to Uint8Array
 */
function hexToBytes(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substr(i, 2), 16);
  }
  return bytes;
}

