    );

    const repositories = response.repositories || [];

    const choices = repositories
      .filter((repo) => repo.full_name.toLowerCase().includes(query.toLowerCase()))
      .slice(0, 25)
      .map((repo) => ({
        name: repo.full_name,
        value: repo.full_name,
