  id: string;
  githubIssueId: string | null;
  linearIssueId: string | null;
  status: IssueStatus;
  isLiveStatusNotifiedOnDiscord: boolean;
  createdAt: number;
  updatedAt: number;
}

export interface DiscordThread {
  id: string;
  issueId: string;
  guildId: string;
  channelId: string;
  threadUrl: string;
  createdAt: number;
}

export interface IssueWithThreads extends Issue {
  discordThreads: DiscordThread[];
}

