import { createStaticKeyProvider, getSecFnSchema } from "@secfn/core";
import type { KeyProvider, SecurityScanner } from "@secfn/core";
import { wrapWithSchema } from "@superfunctions/db";
import { createSecurityScanner } from "@secfn/core";
import { SecFnConfigError } from "@secfn/core";
import { AuditService } from "./audit.js";
import { AccessService } from "./access.js";
import { SecFnRateLimiter } from "./rate-limit.js";
import { createSecFnRouter } from "./router.js";
import type { SecFnRequestContext, SecFnServerConfig } from "./types.js";
import { VaultService } from "./vault.js";

export type * from "./types.js";
export { AuditService, createSecurityLoggerSink } from "./audit.js";
export { AccessService, matchesPermission } from "./access.js";
export { SecFnRateLimiter } from "./rate-limit.js";
export { VaultService } from "./vault.js";
export { createSecFnRouter } from "./router.js";

export interface SecFnServer<TContext extends SecFnRequestContext = SecFnRequestContext> {
  router: ReturnType<typeof createSecFnRouter<TContext>>;
  vault: VaultService;
  access: AccessService;
  rateLimit: SecFnRateLimiter;
  audit: AuditService;
  scanner: SecurityScanner;
  getSchema(): ReturnType<typeof getSecFnSchema>;
}

export function createSecFnServer<TContext extends SecFnRequestContext = SecFnRequestContext>(
  config: SecFnServerConfig<TContext>,
): SecFnServer<TContext> {
  const db = wrapWithSchema(config.db, getSecFnSchema());
  const resolvedConfig = { ...config, db };
  const keyProvider = resolveKeyProvider(config);
  const audit = new AuditService({
    db,
    logger: config.logger,
    sink: config.auditSink,
  });
  const access = new AccessService(db);
  const vault = new VaultService(db, keyProvider, audit);
  const rateLimit = new SecFnRateLimiter(config.rateLimit, audit);
  const scanner = createSecurityScanner();
  const router = createSecFnRouter(resolvedConfig, {
    vault,
    audit,
    access,
    rateLimit,
  });

  return {
    router,
    vault,
    access,
    rateLimit,
    audit,
    scanner,
    getSchema: getSecFnSchema,
  };
}

function resolveKeyProvider<TContext extends SecFnRequestContext>(
  config: SecFnServerConfig<TContext>,
): KeyProvider {
  if (config.keyProvider) return config.keyProvider;
  if (config.encryption?.masterKey) {
    return createStaticKeyProvider(
      config.encryption.masterKey,
      config.encryption.keyId ?? "default",
    );
  }
  throw new SecFnConfigError("SecFn server requires keyProvider or encryption.masterKey");
}

export { getSecFnSchema, getSchema } from "@secfn/core";
import { createRouter, ForbiddenError, TooManyRequestsError, UnauthorizedError, type Route, type RouteContext } from "@superfunctions/http";
import { SecFnForbiddenError, SecFnValidationError } from "@secfn/core";
import type { SecFnRequestContext, SecFnServerConfig, SecFnAdminAction, SecretScope } from "./types.js";
import type { VaultService } from "./vault.js";
import type { AuditService } from "./audit.js";
import type { AccessService } from "./access.js";
import type { SecFnRateLimiter } from "./rate-limit.js";
import { emptyOk, errorResponse, ok, readJson } from "./envelopes.js";

export interface RouterServices {
  vault: VaultService;
  audit: AuditService;
  access: AccessService;
  rateLimit: SecFnRateLimiter;
}

type Context<TContext> = TContext & RouteContext;

const DEFAULT_MAX_BODY_BYTES = 1024 * 1024;

export function createSecFnRouter<TContext extends SecFnRequestContext>(
  config: SecFnServerConfig<TContext>,
  services: RouterServices,
) {
  const adminRoute = (
    method: Route<TContext>["method"],
    path: string,
    action: SecFnAdminAction,
    handler: Route<TContext>["handler"],
  ): Route<TContext> => ({
    method,
    path,
    handler: async (request, ctx) => {
      ctx = await resolveContext(config, ctx);
      if (ctx.namespace && !ctx.tenantId) throw new ForbiddenError("Namespace-scoped access requires tenantId", "SECFN_FORBIDDEN");
      const rate = await services.rateLimit.check({
        userId: ctx.actorId,
        ip: ctx.ip,
        endpoint: new URL(request.url).pathname,
        tenantId: ctx.tenantId,
        namespace: ctx.namespace,
      });
      if (!rate.allowed) throw new TooManyRequestsError("Too many requests", "SECFN_RATE_LIMITED");
      if (!config.authorize) throw new ForbiddenError("Admin authorization is not configured", "SECFN_FORBIDDEN");
      {
        let authorizationRequest: Request;
        if (method === "POST" || method === "PUT" || method === "PATCH") {
          const body = await ctx.text();
          authorizationRequest = new Request(request.url, {
            method: request.method,
            headers: request.headers,
            body,
            signal: request.signal,
          });
        } else {
          authorizationRequest = request.clone();
        }
        const allowed = await config.authorize(ctx, action, { params: { ...ctx.params }, query: Object.fromEntries(ctx.query), request: authorizationRequest });
        if (!allowed) {
          await services.audit.write({
            type: "permission_denied",
            severity: "medium",
            tenantId: ctx.tenantId,
            namespace: ctx.namespace,
            actorId: ctx.actorId,
            ip: ctx.ip,
            userAgent: ctx.userAgent,
            requestId: ctx.requestId,
            resource: `admin:${action}`,
            action,
            metadata: {},
          });
          throw new ForbiddenError("Authorization denied", "SECFN_FORBIDDEN");
        }
      }
      if (!ctx.tenantId && ctx.query.get("namespace")) throw new ForbiddenError("Namespace-scoped access requires tenantId", "SECFN_FORBIDDEN");
      await assertAdminTenant(config, ctx, action);
      return handler(request, ctx);
    },
