import type { DocsConfig } from "@docsfn/core";

const config: DocsConfig = {
  schemaVersion: 1,
  site: {
    title: "MailFn",
    description: "Programmable inboxes, MIME evidence, scoped access, testing, and agent workflows.",
    basePath: "/docs",
    editLink: { pattern: "https://github.com/21nCo/super-functions/edit/dev/mailfn/docs/{path}" },
  },
  compat: { preset: "none" },
  content: {
    root: ".",
    docsDir: "content/docs",
    pagesDir: "content/pages",
    blogDir: "content/blog",
    apiDir: "content/api",
    assetsDir: "static",
    metaFileName: "meta.json",
  },
  navigation: {
    topNav: [
      { label: "Docs", href: "/docs" },
      { label: "Packages", href: "/docs/reference" },
      { label: "GitHub", href: "https://github.com/21nCo/super-functions/tree/dev/mailfn", external: true },
    ],
    sidebars: {
      docs: { title: "Documentation", root: true, include: ["docs/**"] },
    },
  },
  search: { enabled: true, scopes: ["docs"], bodyIndexing: "summary" },
  auth: { enabled: false, mode: "public" },
  analytics: { enabled: false, provider: "watchfn", respectDnt: true },
};

export default config;
<script lang="ts">
  import type { PageData } from "./$types";

  interface Props {
    data: PageData;
  }

  let { data }: Props = $props();

  const tagline = "Programmable inboxes for products, tests, and agents.";
  let configDescription = $derived(data.source.config.site.description ?? "");
  let extraBlurb = $derived(configDescription && configDescription !== tagline ? configDescription : "");

  const features = [
    { title: "Real inbound mail", text: "Accept MIME, persist raw evidence, and parse messages and attachments." },
    { title: "Scoped inboxes", text: "Create stable or expiring inboxes with one-time credentials." },
    { title: "Deterministic waits", text: "Wait for filtered messages and extract verification values." },
    { title: "Composable outbound", text: "Use SendFn for delivery without duplicating providers." },
  ];

  const quickLinks = [
    { label: "Get started", href: "/docs/getting-started", blurb: "Create an inbox and wait for a message." },
    { label: "Cloudflare runtime", href: "/docs/cloudflare-runtime", blurb: "Provision Email, D1, R2, Queues, and secrets." },
    { label: "Testing", href: "/docs/testing", blurb: "Use expiring fixtures and deterministic assertions." },
    { label: "Reference", href: "/docs/reference", blurb: "Package map, operations, and threat-model references." },
  ];
</script>

<svelte:head>
  <title>{data.source.siteTitle}</title>
  <meta name="description" content={data.source.config.site.description ?? tagline} />
</svelte:head>

<div class="landing docsfn-layout">
  <section class="landing-hero" aria-labelledby="landing-title">
    <p class="landing-eyebrow">Open source</p>
    <h1 id="landing-title" class="landing-title">MailFn</h1>
    <p class="landing-tagline">{tagline}</p>
    {#if extraBlurb}
      <p class="landing-sub">{extraBlurb}</p>
    {/if}
  </section>

  <section class="landing-features" aria-label="Highlights">
    <ul class="landing-feature-grid">
      {#each features as item (item.title)}
        <li class="landing-feature">
          <h2 class="landing-feature-title">{item.title}</h2>
          <p class="landing-feature-text">{item.text}</p>
        </li>
      {/each}
    </ul>
  </section>

  <section class="landing-links" aria-label="Quick links">
    <h2 class="landing-section-heading">Explore</h2>
    <div class="landing-cards">
      {#each quickLinks as link (link.href)}
        <a class="landing-card" href={link.href}>
          <span class="landing-card-label">{link.label}</span>
          <p class="landing-card-blurb">{link.blurb}</p>
          <span class="landing-card-cta" aria-hidden="true">→</span>
        </a>
      {/each}
    </div>
  </section>
</div>

